import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.jwovEGr5.js";const s=JSON.parse('{"title":"token增加模式","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"概念学习/ai相关/token增加模式.md","filePath":"概念学习/ai相关/token增加模式.md"}'),i={name:"概念学习/ai相关/token增加模式.md"};function r(l,e,k,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="token增加模式" tabindex="-1">token增加模式 <a class="header-anchor" href="#token增加模式" aria-label="Permalink to &quot;token增加模式&quot;">​</a></h1><p>内容仅供学习参考</p><h2 id="引入" tabindex="-1">引入 <a class="header-anchor" href="#引入" aria-label="Permalink to &quot;引入&quot;">​</a></h2><p>我们与ai进行对话的时候，文字信息会被分解为一个一个最小处理单元，被称为token。</p><p>不仅我们的输入会产生token，ai的上下文分析也同样需要token，那么在我们的对话过程中，token的增加模式是什么样的呢？</p><h2 id="一个误区" tabindex="-1">一个误区 <a class="header-anchor" href="#一个误区" aria-label="Permalink to &quot;一个误区&quot;">​</a></h2><p>或许从直观上来看，从我们的第一个输入开始，到第k个输入，第轮新增1个token，需要与之前k-1个token交互</p><p>那么增加模式应该是累加型，复杂度为<code>O(n²)</code></p><blockquote><p>1+2+...+n = (n^2+n)/2</p></blockquote><h2 id="实际为n2增长" tabindex="-1">实际为n²增长 <a class="header-anchor" href="#实际为n2增长" aria-label="Permalink to &quot;实际为n²增长&quot;">​</a></h2><p>每轮生成时，整个序列重新做注意力计算，第n次需要比较n*n对关系</p><h2 id="工程上的应对" tabindex="-1">工程上的应对 <a class="header-anchor" href="#工程上的应对" aria-label="Permalink to &quot;工程上的应对&quot;">​</a></h2><p>为了缓解n²问题，实际系统会：</p><ol><li>截断上下文：只保留最近N个token（比如4k、8k、128k等上限）</li><li>稀疏注意力：不计算所有n*n对，只计算重要内容</li><li>分层/滑动窗口：远距离token用粗粒度处理，近距离用细粒度</li><li>缓存优化：复用之前算好的部分，避免完全重算</li></ol>',14)])])}const _=a(i,[["render",r]]);export{s as __pageData,_ as default};
